mapper.select:
SELECT id, name, phone, email, gender, age, education, university, major, work_years, current_position, current_company, expected_position, expected_salary, expected_city, skills, work_experience, project_experience, education_history, self_evaluation, file_path, file_type, source, parse_status, parse_error, vectorize_status, indexed FROM resume WHERE deleted = 0
AND parse_status = #{parseStatus}
ORDER BY created_at DESC
